          context_description:
            "The open 2028 Democratic field remains highly fragmented two years out, with prediction markets pricing Alexandria Ocasio-Cortez, Gavin Newsom, and Jon Ossoff as the clearest early leaders due to momentum among progressives, national fundraising reach, and Senate reelection visibility in Georgia. National polling continues to favor Kamala Harris, yet markets discount her standing while elevating Ossoff on the strength of his 2026 contest and populist messaging. Recent progressive primary wins in New York and the DNC’s adoption of a South Carolina-first calendar have sharpened ideological and regional divides, keeping probabilities tightly bunched. Midterm results, formal declarations after November 2026, and early-state retail efforts will likely drive separation among governors, senators, and House progressives.",
